CREATE OR REPLACE FUNCTION public.admin_dispatch_financials(_from timestamptz,_to timestamptz,_driver uuid DEFAULT NULL,_page integer DEFAULT 0) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
DECLARE result jsonb;
BEGIN
IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF;
IF _from IS NULL OR _to IS NULL OR _to<=_from OR _to-_from>interval '31 days' OR _page NOT BETWEEN 0 AND 10000 THEN RAISE EXCEPTION 'Invalid financial period or page'; END IF;
WITH owners AS (SELECT user_id,full_name FROM public.driver_profiles WHERE _driver IS NULL OR user_id=_driver),
wallets AS (SELECT o.user_id,o.full_name,w.currency,w.available_balance,w.pending_balance,w.lifetime_earnings,w.updated_at,coalesce(t.total,0) ledger_balance,coalesce(t.gross,0) ledger_lifetime_earnings,w.provider_user_id IS NOT NULL wallet_exists FROM owners o LEFT JOIN public.provider_wallets w ON w.provider_user_id=o.user_id LEFT JOIN LATERAL(SELECT sum(amount) total,sum(amount) FILTER(WHERE type='job_earning') gross FROM public.wallet_transactions WHERE provider_user_id=o.user_id)t ON true),
ledger AS (SELECT t.*,o.full_name FROM public.wallet_transactions t JOIN owners o ON o.user_id=t.provider_user_id WHERE t.created_at>=_from AND t.created_at<_to),
withdrawals AS (SELECT w.id,w.provider_user_id,o.full_name,w.amount,w.method,w.status,w.created_at,w.updated_at,w.processed_at,w.failure_reason,w.note,(SELECT coalesce(sum(amount),0) FROM public.wallet_transactions WHERE withdrawal_id=w.id AND type='withdrawal') ledger_debit,(SELECT coalesce(sum(amount),0) FROM public.wallet_transactions WHERE withdrawal_id=w.id AND reference='withdrawal:'||w.id||':reversal') ledger_reversal FROM public.provider_withdrawals w JOIN owners o ON o.user_id=w.provider_user_id WHERE w.created_at>=_from AND w.created_at<_to),
jobs AS (SELECT d.id,d.driver_id,o.full_name,d.price,d.payment_method,d.payment_status,d.delivered_at,(SELECT coalesce(sum(amount) FILTER(WHERE type='job_earning'),0) FROM public.wallet_transactions WHERE delivery_id=d.id) gross_earned,(SELECT -coalesce(sum(amount) FILTER(WHERE type='commission'),0) FROM public.wallet_transactions WHERE delivery_id=d.id) commission,(SELECT count(*) FROM public.wallet_transactions WHERE delivery_id=d.id AND type='job_earning') earning_entries,(SELECT count(*) FROM public.wallet_transactions WHERE delivery_id=d.id AND type='commission') commission_entries,(SELECT max(created_at) FROM public.wallet_transactions WHERE delivery_id=d.id) settled_at,public.calc_commission('delivery',coalesce(d.price,0)) current_calculated_commission FROM public.deliveries d JOIN owners o ON o.user_id=d.driver_id WHERE d.status='delivered' AND d.delivered_at>=_from AND d.delivered_at<_to),
payments AS (SELECT p.id,p.delivery_id,p.amount,p.currency,p.payment_method,p.status,p.external_reference,p.failure_reason,p.created_at,p.updated_at,p.paid_at FROM public.payments p JOIN public.deliveries d ON d.id=p.delivery_id JOIN owners o ON o.user_id=d.driver_id WHERE p.created_at>=_from AND p.created_at<_to)
SELECT jsonb_build_object('as_of',now(),'wallets',coalesce((SELECT jsonb_agg(to_jsonb(w)) FROM wallets w),'[]'),
'summary',jsonb_build_object('gross_earned',coalesce((SELECT sum(amount) FROM ledger WHERE type='job_earning'),0),'commission',-coalesce((SELECT sum(amount) FROM ledger WHERE type='commission'),0),'net_earned',coalesce((SELECT sum(amount) FROM ledger WHERE type IN ('job_earning','commission')),0),'withdrawal_statuses',coalesce((SELECT jsonb_object_agg(status,n) FROM (SELECT status,count(*) n FROM withdrawals GROUP BY status)s),'{}'),'wallet_mismatches',(SELECT count(*) FROM wallets WHERE wallet_exists AND (available_balance IS DISTINCT FROM ledger_balance OR lifetime_earnings IS DISTINCT FROM ledger_lifetime_earnings))),
'jobs',coalesce((SELECT jsonb_agg(to_jsonb(j)||jsonb_build_object('net_earned',gross_earned-commission,'settlement_status',CASE WHEN earning_entries=1 AND commission_entries=1 THEN 'Ledger recorded' WHEN payment_status='paid' THEN 'Missing or incomplete ledger' ELSE 'Awaiting confirmed payment' END)) FROM (SELECT * FROM jobs ORDER BY delivered_at DESC,id LIMIT 25 OFFSET _page*25)j),'[]'),'jobs_total',(SELECT count(*) FROM jobs),
'withdrawals',coalesce((SELECT jsonb_agg(to_jsonb(w)) FROM (SELECT * FROM withdrawals ORDER BY created_at DESC,id LIMIT 25 OFFSET _page*25)w),'[]'),'withdrawals_total',(SELECT count(*) FROM withdrawals),
'ledger',coalesce((SELECT jsonb_agg(to_jsonb(t)) FROM (SELECT * FROM ledger ORDER BY created_at DESC,id LIMIT 25 OFFSET _page*25)t),'[]'),'ledger_total',(SELECT count(*) FROM ledger),
'payments',coalesce((SELECT jsonb_agg(to_jsonb(p)) FROM (SELECT * FROM payments ORDER BY created_at DESC,id LIMIT 25 OFFSET _page*25)p),'[]'),'payments_total',(SELECT count(*) FROM payments),'page',_page) INTO result;
RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.admin_dispatch_financials(timestamptz,timestamptz,uuid,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_dispatch_financials(timestamptz,timestamptz,uuid,integer) TO authenticated,service_role;